function drawPlayer(){
 const x=Math.round(player.x),y=Math.round(player.y),run=Math.sin(player.anim)*3,flip=player.face<0;ctx.save();if(flip){ctx.translate(x+player.w,0);ctx.scale(-1,1)}else ctx.translate(x,0);
 const px=flip?0:0; // original character: adventurous explorer, not a licensed hero
 const step=player.onGround?run:0;
 // boots and legs
