canvas.addEventListener('pointerdown',()=>{if(mode==='title'||mode==='over'||mode==='won')startGame();else if(mode==='paused')mode='playing'});
document.querySelectorAll('.touch-btn').forEach(button=>{const key=button.dataset.key;const down=e=>{e.preventDefault();button.classList.add('down');if(key==='left'||key==='right')keys[key]=true;else if(!keys.jump){keys.jump=true;startJump()}};const up=e=>{e.preventDefault();button.classList.remove('down');if(key==='left'||key==='right')keys[key]=false;else keys.jump=false};button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('lostpointercapture',up)});
ui.sound.addEventListener('click',()=>{muted=!muted;ui.sound.textContent=muted?'×':'♫';ui.sound.setAttribute('aria-label',muted?'Ativar som':'Desativar som');if(!muted)sound(600,.08)});
loop();
})();
</script>
</body>
</html>

